import axios from 'axios';
import { useNavigate, Link } from 'react-router-dom';
import AdminSidebar from '../components/AdminSidebar';

const CouponManager = () => {
  const [coupons, setCoupons] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  // Toast State
  const [toast, setToast] = useState({ show: false, message: '', type: 'success' });

  // UI State
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    code: '',
    discountType: 'percentage',
    discountValue: '',
    minPurchase: '',
    expiryDate: ''
  });

  const API_URL = 'http://localhost:5001/api/coupons';

  const fetchCoupons = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('adminToken');
      const { data } = await axios.get(API_URL, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setCoupons(data);
    } catch (err) {
      setError("Failed to fetch coupons.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCoupons();
  }, []);

  const showToast = (message, type = 'success') => {
    setToast({ show: true, message, type });
    setTimeout(() => setToast({ show: false, message: '', type: 'success' }), 3000);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem('adminToken');
      const payload = {
        ...formData,
        discountValue: Number(formData.discountValue),
        minPurchase: Number(formData.minPurchase || 0)
      };

      await axios.post(API_URL, payload, {
        headers: { Authorization: `Bearer ${token}` }
      });

      showToast('Coupon created successfully');
      setFormData({ code: '', discountType: 'percentage', discountValue: '', minPurchase: '', expiryDate: '' });
      setIsModalOpen(false);
      fetchCoupons();
    } catch (err) {
      showToast(err.response?.data?.message || 'Failed to create coupon', 'error');
    }
  };

  const toggleStatus = async (id) => {
    try {
      const token = localStorage.getItem('adminToken');
      await axios.patch(`${API_URL}/${id}/toggle`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      fetchCoupons();
      showToast('Status updated');
    } catch (err) {
      showToast('Failed to toggle status', 'error');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Delete this coupon permanently?')) {
      try {
        const token = localStorage.getItem('adminToken');
        await axios.delete(`${API_URL}/${id}`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        showToast('Coupon deleted');
        fetchCoupons();
      } catch (err) {
        showToast('Failed to delete coupon', 'error');
      }
    }
  };

  return (
    <div className="flex h-screen bg-gray-50 font-display mt-16 overflow-hidden">

      {/* Sidebar (Duplicate of AdminDashboard for consistency) */}
      <aside className="w-64 bg-white shadow-lg border-r border-gray-100 hidden md:flex md:flex-col">
        <div className="h-full flex flex-col pt-5 pb-4 overflow-y-auto">
          <nav className="mt-8 flex-1 px-4 space-y-2">
            <Link to="/admin" className="text-gray-600 hover:bg-gray-50 hover:text-gray-900 group flex items-center px-3 py-2.5 text-sm font-medium rounded-lg">
              Products
            </Link>
            <Link to="/admin/orders" className="text-gray-600 hover:bg-gray-50 hover:text-gray-900 group flex items-center px-3 py-2.5 text-sm font-medium rounded-lg">
              Orders
            </Link>
            <Link to="/admin/advertisements" className="text-gray-600 hover:bg-gray-50 hover:text-gray-900 group flex items-center px-3 py-2.5 text-sm font-medium rounded-lg">
              Advertisements
            </Link>
            <Link to="/admin/coupons" className="bg-gray-100 text-gray-900 group flex items-center px-3 py-2.5 text-sm font-medium rounded-lg">
              Coupons
            </Link>
          </nav>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto w-full p-8">
        <div className="max-w-6xl mx-auto">
          <div className="flex justify-between items-center mb-8">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Coupon Management</h1>
              <p className="text-sm text-gray-500">Create and manage store-wide discount codes.</p>
            </div>
            <button 
              onClick={() => setIsModalOpen(true)}
              className="bg-black text-white px-6 py-2.5 rounded-lg text-sm font-bold uppercase tracking-widest hover:bg-gray-800 transition-all flex items-center gap-2"
            >
              <span className="text-lg">+</span> Create Coupon
            </button>
          </div>

          {loading ? (
             <div className="h-64 flex items-center justify-center text-gray-400">Loading coupons...</div>
          ) : coupons.length === 0 ? (
             <div className="bg-white border-2 border-dashed border-gray-200 rounded-xl p-20 text-center">
                <p className="text-gray-400">No active coupons available.</p>
             </div>
          ) : (
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              <table className="min-w-full divide-y divide-gray-100">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-widest">Code</th>
                    <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-widest">Discount</th>
                    <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-widest">Min. Spend</th>
                    <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-widest">Expiry</th>
                    <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-widest">Status</th>
                    <th className="px-6 py-4 text-right"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {coupons.map((coupon) => (
                    <tr key={coupon._id} className="hover:bg-gray-50 transition-colors group">
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className="font-mono bg-gray-100 px-3 py-1 rounded text-gray-900 font-bold">{coupon.code}</span>
                      </td>
                      <td className="px-6 py-4">
                        <span className="text-sm font-bold text-gray-900">
                          {coupon.discountType === 'percentage' ? `${coupon.discountValue}%` : `₹${coupon.discountValue}`}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-500">₹{coupon.minPurchase || 0}</td>
                      <td className="px-6 py-4 text-sm text-gray-500">
                        {coupon.expiryDate ? new Date(coupon.expiryDate).toLocaleDateString() : 'Never'}
                      </td>
                      <td className="px-6 py-4">
                        <button 
                          onClick={() => toggleStatus(coupon._id)}
                          className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest border ${
                            coupon.isActive ? 'bg-green-50 text-green-600 border-green-100' : 'bg-red-50 text-red-600 border-red-100'
                          }`}
                        >
                          {coupon.isActive ? 'Active' : 'Disabled'}
                        </button>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <button onClick={() => handleDelete(coupon._id)} className="text-gray-300 hover:text-red-500 transition-colors">
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </main>

      {/* Creation Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black bg-opacity-50" onClick={() => setIsModalOpen(false)}></div>
          <div className="relative bg-white rounded-2xl w-full max-w-md shadow-2xl overflow-hidden animate-fade-in-up">
            <div className="px-8 py-6 border-b border-gray-100 flex justify-between items-center">
              <h2 className="text-lg font-bold text-gray-900 uppercase tracking-widest">New Luxury Promo</h2>
              <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-black">✕</button>
            </div>
            <form onSubmit={handleSubmit} className="p-8 space-y-5">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Coupon Code</label>
                <input 
                  name="code" required 
                  value={formData.code} onChange={handleInputChange}
                  placeholder="e.g. BINDASSFIRST"
                  className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-lg outline-none focus:ring-1 focus:ring-black font-mono uppercase"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Type</label>
                  <select 
                    name="discountType" 
                    value={formData.discountType} onChange={handleInputChange}
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-lg outline-none focus:ring-1 focus:ring-black"
                  >
                    <option value="percentage">Percentage (%)</option>
                    <option value="fixed">Fixed (₹)</option>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Value</label>
                  <input 
                    name="discountValue" type="number" required
                    value={formData.discountValue} onChange={handleInputChange}
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-lg outline-none focus:ring-1 focus:ring-black"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Min. Spend</label>
                  <input 
                    name="minPurchase" type="number" 
                    value={formData.minPurchase} onChange={handleInputChange}
                    placeholder="0"
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-lg outline-none focus:ring-1 focus:ring-black"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Expiry Date</label>
                  <input 
                    name="expiryDate" type="date"
                    value={formData.expiryDate} onChange={handleInputChange}
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-lg outline-none focus:ring-1 focus:ring-black"
                  />
                </div>
              </div>

              <button 
                type="submit"
                className="w-full py-4 bg-black text-white text-[10px] font-bold uppercase tracking-[0.3em] rounded-lg shadow-xl hover:bg-gray-800 transition-all transform active:scale-95"
              >
                Launch Promo Code
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Toast */}
      {toast.show && (
        <div className={`fixed bottom-8 right-8 z-[60] px-6 py-3 rounded-lg shadow-2xl animate-fade-in-right flex items-center gap-3 ${
          toast.type === 'success' ? 'bg-emerald-500 text-white' : 'bg-red-500 text-white'
        }`}>
          <span className="text-xs font-bold uppercase tracking-widest">{toast.message}</span>
        </div>
      )}
    </div>
  );
};

export default CouponManager;
